using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Swashbuckle.AspNetCore.Annotations;using GraphApi.Models.FNZ.Transacciones;using GraphApi.Services.FNZ.Transacciones;namespace GraphApi.Controllers.FNZ.Transacciones{    /// <summary>    /// Gestión de Transacciones: consulta, creación, actualización y borrado.    /// </summary>    [ApiController]    [Authorize]    [Route("FNZ/[controller]")]    [Produces("application/json")]    [SwaggerTag("Operaciones sobre Transacciones")]    public class TransaccionesController : Controller    {        private readonly ITransaccionesService _objService;        public TransaccionesController(ITransaccionesService objService)        {            _objService = objService;        }        /// <summary>        /// Obtiene todos los Transacciones, con filtros opcionales.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="transaccionID">TransaccionID</param>        /// <param name="cuentaID">CuentaID</param>        /// <param name="cuenta">Cuenta</param>        /// <param name="tipoCuenta">TipoCuenta</param>        /// <param name="usuarioID">UsuarioID</param>        /// <param name="nombreUsuario">NombreUsuario</param>        /// <param name="tipoMovimientoID">TipoMovimientoID</param>        /// <param name="tipoMovimiento">TipoMovimiento</param>        /// <param name="cargo">Cargo</param>        /// <param name="abono">Abono</param>        /// <param name="motivo">Motivo</param>        /// <param name="bEliminado">bEliminado</param>        /// <returns>Listado de Transacciones</returns>        [HttpGet]        [SwaggerOperation(            Summary = "Listar Transacciones",            Description = "Devuelve Transacciones aplicando filtros opcionales."        )]        [ProducesResponseType(typeof(IEnumerable<clReadTransacciones>), StatusCodes.Status200OK)]        public async Task<ActionResult<IEnumerable<clReadTransacciones>>> GetAll(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromQuery] int? transaccionID,            [FromQuery] int? cuentaID,            [FromQuery] string? cuenta,            [FromQuery] string? tipoCuenta,            [FromQuery] int? usuarioID,            [FromQuery] string? nombreUsuario,            [FromQuery] int? tipoMovimientoID,            [FromQuery] string? tipoMovimiento,            [FromQuery] decimal? cargo,            [FromQuery] decimal? abono,            [FromQuery] string? motivo,            [FromQuery] bool? bEliminado,            [FromQuery] string? columnNames)        {            var vList = await _objService.GetTransaccionesDynamic(                transaccionID,                 cuentaID,                 cuenta,                 tipoCuenta,                 usuarioID,                 nombreUsuario,                 tipoMovimientoID,                 tipoMovimiento,                 cargo,                 abono,                 motivo,                 bEliminado,                 columnNames, nUserId, sWindowName);              return vList.Count()==0  ? NotFound() :  Ok(vList);        }        /// <summary>        /// Crea un nuevo Transaccione.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="input">Datos del Transaccione a crear.</param>        /// <returns>El Transaccione recién creado.</returns>        [HttpPost]        [SwaggerOperation(            Summary = "Crear Transacciones",            Description = "Inserta un nuevo Transaccione en la base de datos."        )]        [ProducesResponseType(typeof(clReadTransacciones), StatusCodes.Status201Created)]        public async Task<ActionResult<clReadTransacciones>> Create(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromBody] clCreateTransacciones objInput)        {            var vCreated = await _objService.CreateTransacciones(objInput, nUserId, sWindowName);            return vCreated is null ? NoContent() : vCreated;        }        /// <summary>        /// Actualización parcial de Transaccione.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="input">Campos a actualizar y el ID del Transaccione.</param>        /// <returns>El Transaccione actualizado.</returns>        [HttpPatch]        [SwaggerOperation(            Summary = "Actualizar Transacciones",            Description = "Actualiza uno o varios campos de Transaccione existente."        )]        [ProducesResponseType(typeof(clReadTransacciones), StatusCodes.Status200OK)]        public async Task<ActionResult<clReadTransacciones>> Patch(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromBody] clUpdateTransacciones objInput)        {            var vUpdated = await _objService.UpdateTransacciones(objInput, nUserId, sWindowName);            return vUpdated is null ? NotFound() : Ok(vUpdated);        }        /// <summary>        /// Elimina un Transaccione por su ID.        /// </summary>        [HttpDelete("{nTransaccionesID:int}")]        [SwaggerOperation(            Summary = "Eliminar Transaccione",            Description = "Borra un Transaccione si existe."        )]        [ProducesResponseType(StatusCodes.Status204NoContent)]        public async Task<IActionResult> Delete(int nTransaccionesID)        {            var success = await _objService.DeleteTransacciones(nTransaccionesID);            return success ? NoContent() : NotFound();        }    }}